WITH flattened AS (SELECT id, currency, val FROM price_tiers LATERAL VIEW EXPLODE(discounts) li AS val) SELECT CASE WHEN val >= 90 THEN 'LARGE' ELSE 'SMALL' END AS val_tier, currency, SIZE(COLLECT_SET(currency)) AS num_currencies, COUNT(DISTINCT id) AS distinct_ids, PERCENTILE_APPROX(val, 0.9) AS val_p90 FROM flattened GROUP BY val_tier, currency HAVING PERCENTILE_APPROX(val, 0.9) > 0 ORDER BY val_p90 DESC
